7	// A business operation that stays pending until the test releases it, plus a
8	// promise that fires once the engine has actually invoked it (and is therefore
9	// parked on its await).
10	function gatedHold(name = 'hold', result = 'p') {
11	  let release;
12	  const gate = new Promise(resolve => { release = resolve; });
13	  let markStarted;
14	  const started = new Promise(resolve => { markStarted = resolve; });
15	  let invocations = 0;
16	  const operations = {
17	    [name]: () => {
18	      invocations += 1;
19	      markStarted();
20	      return gate.then(() => result);
21	    },
22	  };
23	  return { release, started, operations, invocationCount: () => invocations };
24	}
