26	// start -> check (vip === true) -> then: priority (business "hold") -> wrap
27	//                              -> else: standard (message action)  -> wrap
28	// wrap dependsOn initialDeps -> done. With vip true the run parks inside
29	// "hold"; "standard" is on the branch never taken, so a wrap that depends on
30	// it can only end blocked, while a wrap depending on "priority" alone
31	// completes once the hold resolves. Extra nodes are appended after the end
32	// node, so their validation happens only after wrap's dependencies were
33	// already checked.
34	function blockedWorkflow({ initialDeps, compensable = false, extraNodes = [] } = {}) {
35	  const wrapNode = { id: 'wrap', type: 'action', dependsOn: initialDeps, next: 'done' };
36	  const priorityNode = { id: 'priority', type: 'action', operation: 'hold', next: 'wrap' };
37	  if (compensable) priorityNode.compensation = { operation: 'undo' };
38	  const workflow = {
39	    id: 'dependency-isolation', entry: 'start',
40	    nodes: [
41	      { id: 'start', type: 'trigger', next: 'check' },
42	      {
43	        id: 'check', type: 'condition',
44	        condition: { field: 'vip', operator: 'eq', value: true },
45	        then: 'priority', else: 'standard',
46	      },
47	      priorityNode,
48	      { id: 'standard', type: 'action', message: 'standard', next: 'wrap' },
49	      wrapNode,
50	      { id: 'done', type: 'end', result: 'done' },
51	      ...extraNodes,
52	    ],
53	  };
54	  return { workflow, wrapNode };
55	}
