78	// Park the run inside "hold", run `mutate` while it waits, then resume.
79	async function parkMutateAndResume(workflow, input, operations, mutate) {
80	  const hold = gatedHold();
81	  const merged = { ...hold.operations, ...operations };
82	  const runPromise = executeWorkflowAsync(workflow, input, merged);
83	  await hold.started;
84	  // Let the engine settle onto its await of the pending operation.
85	  await sleep(5);
86	  mutate();
87	  hold.release();
88	  return runPromise;
89	}
