// start -> action(business "work", waits) -> process-order -> done
//                                   notify (legal, not originally connected) -> done
const processNode = { id: 'process-order', type: 'action', message: '处理订单', next: 'done' };
const notifyNode = { id: 'send-notify', type: 'action', message: '发送通知', next: 'done' };
const workflow = {
  id: 'repro', entry: 'start',
  nodes: [
    { id: 'start', type: 'trigger', next: 'work' },
    {
      id: 'work', type: 'action', operation: 'work',
      next: 'process-order',
    },
    processNode,
    notifyNode,
    { id: 'done', type: 'end', result: 'finished' },
  ],
};

const operations = {
  work: () => {
    started();
    return gate.then(() => 'work-done');
  },
};

const runPromise = executeWorkflowAsync(workflow, {}, operations);
await startedGate;
await sleep(5);

// While the run is parked on "work":
// 1. change work.next to a legal existing successor "send-notify"
// 2. make another node point to a nonexistent target, so validation fails
const workNode = workflow.nodes[1];
workNode.next = 'send-notify';
processNode.next = 'ghost-target';
try {
  validateWorkflow(workflow);
  console.log('UNEXPECTED: validation passed');
} catch (error) {
  console.log('validation rejected as expected:', error.message);
}

// Restore the definition to its pre-edit content WITHOUT revalidating.
workNode.next = 'process-order';
processNode.next = 'done';

// Resume the parked run.
release();
const result = await runPromise;
console.log('status:', result.status);
console.log('trace:', result.trace.map(n => n.nodeId));
console.log('output keys:', Object.keys(result.context.output));
console.log('result:', result.result);

